// Reproducible rendering inputs generated by the actual wallpaper model.
#include "nexusmodel.h"
#include <QCoreApplication>
#include <QDateTime>
#include <QDir>
#include <QFile>
#include <QJsonArray>
#include <QJsonDocument>
#include <QJsonObject>

int main(int argc, char **argv)
{
    QCoreApplication app(argc, argv);
    if (app.arguments().size() != 2) return 2;
    const QString output = app.arguments().at(1);
    QDir().mkpath(output);
    qint64 epoch = QDateTime(QDate(2026, 11, 8), QTime(0, 0)).toMSecsSinceEpoch();
    NexusModel model({4196, 1280}, epoch, 42);
    for (int t = 0; t <= 17000; t += 45) model.advance(epoch + t);
    QJsonArray frames;
    for (int frame = 0; frame < 240; ++frame) {
        qint64 now = epoch + 17000 + qRound(frame * 1000.0 / 30.0);
        model.advance(now);
        if (frame == 30) model.tap({1900, 640}, now);
        if (frame == 120) model.tap({2950, 820}, now);
        QString name = QString("state-%1.png").arg(frame, 3, 10, QLatin1Char('0'));
        if (!model.image().save(output + '/' + name, "PNG")) return 3;
        frames.append(QJsonObject{{"file", name}, {"seconds", (now - epoch) / 1000.0}, {"extraCount", model.extraCount()}});
    }
    // A before/after pair at the same time isolates the four click trails.
    NexusModel test({1000, 400}, epoch, 42);
    test.image().save(output + "/click-before.png", "PNG");
    test.tap({490, 200}, epoch);
    test.image().save(output + "/click-after.png", "PNG");
    // Same deterministic canvas at the midnight boundary.
    NexusModel midnight({1000, 400}, epoch + 86399500, 42);
    midnight.tap({490, 200}, epoch + 86399500);
    midnight.image().save(output + "/midnight.png", "PNG");
    QFile file(output + "/frames.json");
    if (!file.open(QIODevice::WriteOnly)) return 4;
    file.write(QJsonDocument(frames).toJson());
    return 0;
}
